import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { createServer } from "node:http";
import { mkdtemp, readFile, writeFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { resolve, join } from "node:path";
import { setTimeout as pause } from "node:timers/promises";
import { loadConfig } from "../src/config.js";
import { SqliteOrchestratorState } from "../src/sqlite-store.js";
import { OrchestratorApplication } from "../src/application.js";
import { PiBenchmarkRuntime } from "../src/benchmark-runtime.js";
import { createStrictForgeOutput } from "../src/strict-forge-output.js";
const root=resolve("../..");
const evidence=join(root,".forge/benchmarks/schema-descriptions-ready-20260908");
const fixture=JSON.parse(await readFile(join(evidence,"sdk-smoke-fixture.json"),"utf8"));
const catalog=JSON.parse(await readFile(join(root,"agent/contracts/forge-output-descriptions-v1.json"),"utf8"));
const canonical=JSON.parse(await readFile(join(root,"forge/schema.json"),"utf8"));
const hash=(v:unknown)=>"sha256:"+createHash("sha256").update(JSON.stringify(v)).digest("hex");
function deref(s:any,whole:any):any { return s.$ref==="#"?whole:s.$ref?deref(s.$ref.slice(2).split("/").reduce((n:any,k:string)=>n[k],whole),whole):s; }
function fits(v:any,s:any,whole:any):boolean {
  s=deref(s,whole);
  if(s.anyOf) return s.anyOf.some((n:any)=>fits(v,n,whole));
  if(s.enum&&!s.enum.includes(v))return false;
  if(s.type==="null")return v===null;
  if(s.type==="string")return typeof v==="string";
  if(s.type==="number"||s.type==="integer")return typeof v==="number";
  if(s.type==="boolean")return typeof v==="boolean";
  if(s.type==="array")return Array.isArray(v)&&v.every((n:any)=>fits(n,s.items,whole));
  if(s.type==="object")return v!==null&&typeof v==="object"&&!Array.isArray(v)&&Object.entries(v).every(([k,n])=>s.properties[k]&&fits(n,s.properties[k],whole));
  return true;
}
function strict(v:any,s:any,whole:any):any {
  s=deref(s,whole);
  if(s.anyOf){const branch=s.anyOf.find((n:any)=>fits(v,n,whole));assert.ok(branch,"No strict branch for historical candidate");return strict(v,branch,whole);}
  if(v===null)return null;
  if(Array.isArray(v))return v.map(n=>strict(n,s.items,whole));
  if(s.type==="object")return Object.fromEntries(s.required.map((k:string)=>[k,k in v?strict(v[k],s.properties[k],whole):null]));
  return v;
}
function withoutDescriptions(v:any):any {if(Array.isArray(v))return v.map(withoutDescriptions);if(v&&typeof v==="object")return Object.fromEntries(Object.entries(v).filter(([k])=>k!=="description").map(([k,n])=>[k,withoutDescriptions(n)]));return v;}
const directory=await mkdtemp(join(tmpdir(),"forge-schema-real-sdk-"));
const requests:any[]=[];
const network:string[]=[];
const nativeFetch=globalThis.fetch;
globalThis.fetch=async(input:any,init?:any)=>{
  const url=new URL(typeof input==="string"||input instanceof URL?input:input.url);
  assert.equal(url.hostname,"127.0.0.1","External network is forbidden in this smoke");network.push(url.pathname);
  return nativeFetch(input,init);
};
const provider=createServer(async(req,res)=>{
  try{
    let raw="";for await(const part of req)raw+=part;
    const body=JSON.parse(raw);requests.push(body);
    const tool=body.tools?.[0]?.function;
    let delta:any,finish:string;
    if(tool){
      assert.equal(tool.name,"emit_forge_query");assert.equal(tool.strict,true);
      const args=strict(fixture.forge,tool.parameters,tool.parameters);
      const mode=tool.parameters.properties.scan.description?"interfaces-v1":"off";
      assert.deepEqual(createStrictForgeOutput(canonical,catalog.profiles[mode].descriptions).decode(args),fixture.forge);
      delta={role:"assistant",tool_calls:[{index:0,id:"synthetic-call",type:"function",function:{name:tool.name,arguments:JSON.stringify(args)}}]};finish="tool_calls";
    }else{delta={role:"assistant",content:fixture.direct};finish="stop";}
    res.writeHead(200,{"content-type":"text/event-stream"});
    const chunk=(choices:any[],usage?:any)=>res.write("data: "+JSON.stringify({id:"synthetic-response",object:"chat.completion.chunk",created:0,model:"fixture",choices,...(usage?{usage}:{})})+"\n\n");
    chunk([{index:0,delta,finish_reason:null}]);chunk([{index:0,delta:{},finish_reason:finish}]);
    chunk([],{prompt_tokens:100,completion_tokens:50,total_tokens:150});res.end("data: [DONE]\n\n");
  }catch(error){console.error(error);res.writeHead(500);res.end("Synthetic fixture failed");}
});
await new Promise<void>(r=>provider.listen(0,"127.0.0.1",r));
const port=(provider.address() as any).port;
await writeFile(join(directory,"models.json"),JSON.stringify({providers:{"local-schema-smoke":{baseUrl:`http://127.0.0.1:${port}/v1`,api:"openai-completions",apiKey:"synthetic-not-a-real-key",authHeader:true,models:[{id:"fixture",name:"Deterministic historical replay — not a model",reasoning:false,input:["text"],contextWindow:128000,maxTokens:16384,cost:{input:0,output:0,cacheRead:0,cacheWrite:0},compat:{supportsDeveloperRole:false,supportsReasoningEffort:false,supportsStrictMode:true}}]}}}));
await writeFile(join(directory,"auth.json"),"{}");
const config=loadConfig({PI_ORCHESTRATOR_AGENT_DIR:directory,PI_ORCHESTRATOR_STATE_DB:join(directory,"state.sqlite"),SHISUI_DATA_SKILLS_DIR:directory,PI_BENCHMARK_CONCURRENCY:"1",FORGE_BASE_URL:"http://127.0.0.1:19043",FORGE_PI_SERVICE_KEY:"synthetic-schema-smoke"});
const state=new SqliteOrchestratorState(config.stateDbPath);
const application=new OrchestratorApplication({config,state});
const runtime=new PiBenchmarkRuntime(config,application);
const runs:any[]=[];
try{
  const unauthorized=await fetch(config.forgeBaseUrl+"/api/internal/benchmark-v2/suite");assert.equal(unauthorized.status,401);
  for(const mode of ["off","interfaces-v1"]){
    const frozen=JSON.parse(await readFile(join(evidence,`synthetic-${mode}.frozen.json`),"utf8"));
    const started=await runtime.start({provider:"local-schema-smoke",model:"fixture",caseIds:[fixture.case_id],confirmModelCalls:2,protocolManifest:frozen.manifest});
    let run:any;
    for(let i=0;i<600;i++){run=runtime.get(started.run_id);if(["completed","failed","stopped","interrupted"].includes(run.status))break;await pause(50);}
    assert.equal(run.status,"completed",JSON.stringify({run,logs:runtime.logs(started.run_id)}));
    assert.equal(run.completed_calls,2);assert.equal(run.generation_contract.schema_descriptions.mode,mode);
    assert.equal(run.generation_contract.forge_wire_schema_revision,catalog.profiles[mode].wire_schema_revision);
    for(const arm of ["forge","direct"]){assert.equal(run.cases[0][arm].evidence.dispatches,1);assert.equal(run.cases[0][arm].usage_observed,true);}
    runs.push(run);
  }
  assert.equal(requests.length,4);
  const forge=requests.filter(r=>r.tools?.length),direct=requests.filter(r=>!r.tools?.length);
  assert.deepEqual(direct[0],direct[1]);assert.deepEqual(withoutDescriptions(forge[0]),withoutDescriptions(forge[1]));
  assert.equal(hash(forge[0].tools[0].function.parameters),catalog.profiles.off.wire_schema_revision);
  assert.equal(hash(forge[1].tools[0].function.parameters),catalog.profiles["interfaces-v1"].wire_schema_revision);
  assert.deepEqual(runs[0].cases[0].forge.output,runs[1].cases[0].forge.output);
  assert.equal(runs[0].cases[0].direct.output,runs[1].cases[0].direct.output);
  const forged=JSON.parse(await readFile(join(evidence,"synthetic-interfaces-v1.frozen.json"),"utf8"));forged.manifest.schema_descriptions.mode="unknown";
  await assert.rejects(runtime.start({provider:"local-schema-smoke",model:"fixture",caseIds:[fixture.case_id],confirmModelCalls:2,protocolManifest:forged.manifest}));
  assert.equal(requests.length,4);
  const result={status:"passed",boundary:"real Pi SDK and real authenticated Python HTTP routes; only provider responses are deterministic loopback replay",new_model_calls:0,synthetic_sse_dispatches:requests.length,external_network_requests:0,unauthorized_http_status:unauthorized.status,direct_payload_identical:true,forge_payload_identical_except_descriptions:true,candidate_outputs_identical:true,forged_mode_rejected_before_dispatch:true,runs:runs.map(r=>({protocol_revision:r.protocol_revision,generation_contract:r.generation_contract,status:r.status,completed_synthetic_dispatches:r.completed_calls,candidate_hashes:{forge:hash(r.cases[0].forge.output),direct:hash(r.cases[0].direct.output)}})),network_paths:network};
  await writeFile(join(evidence,"real-sdk-http-smoke.json"),JSON.stringify(result,null,2),{flag:"wx"});
  console.log(JSON.stringify(result));
}finally{await runtime.close();state.close();await new Promise<void>(r=>provider.close(()=>r()));globalThis.fetch=nativeFetch;await rm(directory,{recursive:true,force:true});}

