import hashlib, json, sys, types
from pathlib import Path
module=types.ModuleType("config");module.cfg=types.SimpleNamespace();sys.modules["config"]=module
from forge import hard_accuracy_benchmark as hard
from forge.benchmark_service import build_context_response
root=Path(".forge/benchmarks/schema-descriptions-ready-20260908")
baseline=json.loads((root/"baseline-input-hashes.json").read_text())["cases"]
def digest(value):return "sha256:"+hashlib.sha256(json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(",",":"),allow_nan=False).encode()).hexdigest()
current={}
for case in hard.load_suite(hard._FULL_SUITE_ID)["cases"]:
    ctx=build_context_response(hard.load_suite(hard._FULL_SUITE_ID),case)
    current[case["case_id"]]={"snapshot":digest(ctx["context_snapshot"]),"schema":digest(ctx["schema_context"]),"forge":digest(ctx["forge_instructions"]),"direct":digest(ctx["direct_instructions"])}
assert current==baseline
result={"public_cases":len(current),"checked_fields":["context_snapshot","schema_context","forge_instructions","direct_instructions"],"unchanged":len(current),"new_model_calls":0,"gold_executions":0}
with (root/"input-invariance.json").open("x") as f:json.dump(result,f,indent=2)
print(json.dumps(result))
